def _glom_match(target, spec, scope):
    if isinstance(spec, Match):
        return spec.glomit(target, scope)

    if isinstance(spec, dict):
        return _handle_dict(target, spec, scope)

    if isinstance(spec, (list, tuple)):
        if not isinstance(target, type(spec)):
            raise MatchError("target {0!r} is not a {1}", target, type(spec).__name__)
        if len(spec) == 0:
            if len(target) != 0:
                raise MatchError("target {0!r} is not empty", target)
            return target
        if len(spec) == 1:
            spec_item = spec[0]
            ret = type(spec)([scope[glom](item, spec_item, scope) for item in target])
            return ret
        else:
            if len(target) != len(spec):
                raise MatchError("target {0!r} length {1} != spec length {2}", target, len(target), len(spec))
            ret = type(spec)([scope[glom](target[i], spec[i], scope) for i in range(len(spec))])
            return ret

    if isinstance(spec, (set, frozenset)):
        if not isinstance(target, type(spec)):
            raise MatchError("target {0!r} is not a {1}", target, type(spec).__name__)
        if len(spec) == 0:
            if len(target) != 0:
                raise MatchError("target {0!r} is not empty", target)
            return target
        if len(spec) == 1:
            spec_item = list(spec)[0]
            ret = type(spec)([scope[glom](item, spec_item, scope) for item in target])
            return ret
        else:
            raise MatchError("set/frozenset specs must be empty or have exactly one element")

    if isinstance(spec, type):
        if not isinstance(target, spec):
            raise TypeMatchError(target, spec)
        return target

    if hasattr(spec, 'glomit'):
        return scope[glom](target, spec, scope)

    if target == spec:
        return target

    raise MatchError("target {0!r} does not match {1!r}", target, spec)
